/**
 * Drawing a streamed mesh once what it is drawn with is built.
 *
 * On WebGPU a draw needs a render pipeline for its exact state: shader,
 * vertex layout, blending, depth, the target's formats. Babylon builds a
 * missing one on the spot with `createRenderPipeline`, which on a first
 * visit holds the GPU for 100 to 400 ms while it compiles, so the whole
 * frame freezes. Here a mesh asked for with `compileAhead` has a missing
 * pipeline built in the background with `createRenderPipelineAsync`, from
 * the same state the draw asked for, and is left out of the frames until it
 * is ready: a new kind of terrain appears a few frames late instead of
 * stopping the world.
 *
 * Only meshes that stream in as the visitor moves are asked for. Anything
 * drawn once (a reflection captured once, a screenshot) would keep the gap,
 * and everything else draws as before.
 *
 * It wraps Babylon's WebGPU pipeline cache (`getRenderPipeline`) and
 * `Mesh._draw`; tests/unit/compileAhead.test.ts fails if an upgrade moves
 * what it relies on.
 */
import type { AbstractEngine } from '@babylonjs/core/Engines/abstractEngine';
import type { AbstractMesh } from '@babylonjs/core/Meshes/abstractMesh';
import { Mesh } from '@babylonjs/core/Meshes/mesh';

const asked = new WeakSet<object>();

/** Asks that `mesh` be drawn only once what it is drawn with is built. */
export function compileAhead(mesh: AbstractMesh): void {
  asked.add(mesh);
}

/** Whether `mesh` is drawn only once what it is drawn with is built. */
export function isCompileAhead(mesh: AbstractMesh): boolean {
  return asked.has(mesh);
}

// The engine frame an asked-for mesh was last left out in, and last drawn in.
const leftOutAt = new WeakMap<object, number>();
const drewAt = new WeakMap<object, number>();
const frameOf = (mesh: { getEngine(): unknown }): number => (mesh.getEngine() as { frameId?: number }).frameId ?? 0;

/**
 * Whether `mesh` was left out of its last frame drawn, a pipeline it needs still being built. A mesh shown in place
 * of another while it waits leaves a hole: keep the other until this says no.
 */
export function pipelineWaiting(mesh: AbstractMesh): boolean {
  const out = leftOutAt.get(mesh);
  if (out === undefined) return false;
  const drew = drewAt.get(mesh);
  return drew === undefined || drew <= out;
}

/** Babylon's WebGPU render pipeline cache, as far as it is used here. */
interface PipelineCache {
  disabled: boolean;
  _parameter: { token: object | undefined; pipeline: unknown };
  _device: { createRenderPipelineAsync(descriptor: unknown): Promise<unknown> };
  getRenderPipeline(fillMode: number, effect: unknown, sampleCount: number, textureState?: number): unknown;
  _lookupRenderPipeline(fillMode: number, effect: unknown, sampleCount: number, textureState: number): unknown;
  _buildRenderPipelineDescriptor(effect: unknown, topology: unknown, sampleCount: number): unknown;
  _setRenderPipeline(param: { token: object; pipeline: unknown }): void;
}

/** Thrown from inside an asked-for mesh's draw to leave it out of this frame; caught at that mesh's draw. */
const LEFT_OUT = { leftOut: 'its pipeline is being built' };

/** Whether the draw under way is an asked-for mesh's. */
let drawingAsked = false;

type DrawFn = (this: AbstractMesh, ...args: unknown[]) => unknown;
const meshPatches = new WeakMap<object, { original: DrawFn; installs: number }>();

const patchMeshDraw = (prototype: { _draw: DrawFn }): (() => void) => {
  let patch = meshPatches.get(prototype);
  if (!patch) {
    const original = prototype._draw;
    patch = { original, installs: 0 };
    meshPatches.set(prototype, patch);
    prototype._draw = function (this: AbstractMesh, ...args: unknown[]) {
      if (!asked.has(this)) return original.apply(this, args);
      const was = drawingAsked;
      drawingAsked = true;
      try {
        const drawn = original.apply(this, args);
        drewAt.set(this, frameOf(this));
        return drawn;
      } catch (e) {
        if (e === LEFT_OUT) {
          leftOutAt.set(this, frameOf(this));
          return this;
        }
        throw e;
      } finally {
        drawingAsked = was;
      }
    };
  }
  patch.installs++;
  return () => {
    const p = meshPatches.get(prototype);
    if (!p || --p.installs > 0) return;
    prototype._draw = p.original;
    meshPatches.delete(prototype);
  };
};

/**
 * Builds the pipelines of asked-for meshes in the background on `engine`, a
 * WebGPU engine; on any other it does nothing. Returns its uninstall.
 */
export function installCompileAhead(engine: AbstractEngine, meshPrototype: object = Mesh.prototype): () => void {
  const cache = (engine as unknown as { _cacheRenderPipeline?: PipelineCache })._cacheRenderPipeline;
  if (!cache || typeof cache._lookupRenderPipeline !== 'function' || typeof cache._device?.createRenderPipelineAsync !== 'function') {
    return () => {};
  }
  const getTopology = (cache.constructor as unknown as { _GetTopology(fillMode: number): unknown })._GetTopology;
  const building = new WeakSet<object>();
  const failed = new WeakSet<object>();
  const original = cache.getRenderPipeline;
  const ownBefore = Object.prototype.hasOwnProperty.call(cache, 'getRenderPipeline');
  cache.getRenderPipeline = function (this: PipelineCache, fillMode: number, effect: unknown, sampleCount: number, textureState = 0) {
    if (!drawingAsked || this.disabled) return original.call(this, fillMode, effect, sampleCount, textureState);
    // WebGPU draws with 1 or 4 samples, as the cache's own lookup takes them.
    const samples = sampleCount > 1 ? 4 : 1;
    const built = this._lookupRenderPipeline(fillMode, effect, samples, textureState);
    if (built) return built;
    const token = this._parameter.token;
    // A pipeline whose background build failed is built on the spot, as Babylon would, so its error shows as it would.
    if (!token || failed.has(token)) return original.call(this, fillMode, effect, sampleCount, textureState);
    if (!building.has(token)) {
      building.add(token);
      const descriptor = this._buildRenderPipelineDescriptor(effect, getTopology(fillMode), samples);
      this._device.createRenderPipelineAsync(descriptor).then(
        (pipeline) => {
          building.delete(token);
          this._setRenderPipeline({ token, pipeline });
        },
        () => {
          building.delete(token);
          failed.add(token);
        },
      );
    }
    throw LEFT_OUT;
  };
  const unpatchMesh = patchMeshDraw(meshPrototype as { _draw: DrawFn });
  return () => {
    if (ownBefore) cache.getRenderPipeline = original;
    else delete (cache as Partial<PipelineCache>).getRenderPipeline;
    unpatchMesh();
  };
}
